INSERT OR IGNORE INTO cms_versions(id,record_id,revision,data,actor,action,created_at) SELECT 'stock-20261012-draft-'||id,id,revision,draft,'site-release','before-confirmed-stock-update',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM cms_records WHERE kind='collection' AND slug IN ('smiley','thank-you') AND archived=0 AND json_extract(draft,'$.collection.variants')=json('[{"id":"gsm-50","gsm":50,"color":"To be confirmed","colorSq":"Për t’u konfirmuar","status":"check"},{"id":"gsm-60","gsm":60,"color":"To be confirmed","colorSq":"Për t’u konfirmuar","status":"check"}]');
