UPDATE cms_records SET draft=CASE WHEN json_extract(draft,'$.collection.variants')=json('[{"id":"gsm-50","gsm":50,"color":"To be confirmed","colorSq":"Për t’u konfirmuar","status":"check"},{"id":"gsm-60","gsm":60,"color":"To be confirmed","colorSq":"Për t’u konfirmuar","status":"check"}]') THEN json_set(draft,'$.collection.variants',json('[{"id":"gsm-50-white","gsm":50,"color":"White","colorSq":"E bardhë","status":"available"},{"id":"gsm-60-white","gsm":60,"color":"White","colorSq":"E bardhë","status":"available"},{"id":"gsm-60-beige","gsm":60,"color":"Beige","colorSq":"Bezhë","status":"available"},{"id":"gsm-60-black","gsm":60,"color":"Black","colorSq":"E zezë","status":"available"},{"id":"gsm-60-red","gsm":60,"color":"Red","colorSq":"E kuqe","status":"available"}]')) ELSE draft END,published=CASE WHEN json_extract(published,'$.collection.variants')=json('[{"id":"gsm-50","gsm":50,"color":"To be confirmed","colorSq":"Për t’u konfirmuar","status":"check"},{"id":"gsm-60","gsm":60,"color":"To be confirmed","colorSq":"Për t’u konfirmuar","status":"check"}]') THEN json_set(published,'$.collection.variants',json('[{"id":"gsm-50-white","gsm":50,"color":"White","colorSq":"E bardhë","status":"available"},{"id":"gsm-60-white","gsm":60,"color":"White","colorSq":"E bardhë","status":"available"},{"id":"gsm-60-beige","gsm":60,"color":"Beige","colorSq":"Bezhë","status":"available"},{"id":"gsm-60-black","gsm":60,"color":"Black","colorSq":"E zezë","status":"available"},{"id":"gsm-60-red","gsm":60,"color":"Red","colorSq":"E kuqe","status":"available"}]')) ELSE published END,revision=revision+1,mutation='confirmed-stock-20261012',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE kind='collection' AND slug IN ('smiley','thank-you') AND archived=0 AND (json_extract(draft,'$.collection.variants')=json('[{"id":"gsm-50","gsm":50,"color":"To be confirmed","colorSq":"Për t’u konfirmuar","status":"check"},{"id":"gsm-60","gsm":60,"color":"To be confirmed","colorSq":"Për t’u konfirmuar","status":"check"}]') OR json_extract(published,'$.collection.variants')=json('[{"id":"gsm-50","gsm":50,"color":"To be confirmed","colorSq":"Për t’u konfirmuar","status":"check"},{"id":"gsm-60","gsm":60,"color":"To be confirmed","colorSq":"Për t’u konfirmuar","status":"check"}]'));
